import java.util.regex.*;

public class PatternDemo {
    public static void main(String[] args) {
        Pattern p = Pattern.compile("[A-F]{5,}.*");
        String str = "AAAAAhhh";
        Matcher match = p.matcher(str);
        System.out.println(match.matches());   // true
    }
}

import java.util.regex.*;

public class FindDemo {
    public static void main(String[] args) {
        Pattern p = Pattern.compile("[0-9]");
        String str = "Passw0rd";
        Matcher match = p.matcher(str);
        System.out.println(match.find());      // true
    }
}

Pattern p = Pattern.compile("[0-9]");
Matcher m = p.matcher("Passw0rd");

System.out.println(m.matches());   // false, the whole string is not a single digit
System.out.println(m.find());      // true, a digit exists somewhere inside

Pattern p = Pattern.compile("\\d+");
Matcher m = p.matcher("Order 12 shipped 2024 units in 7 boxes");

while (m.find()) {
    System.out.println(m.group());     // 12, then 2024, then 7
}

Pattern p = Pattern.compile("(\\d{3})-(\\d{4})");
Matcher m = p.matcher("Call 555-1234 now");

if (m.find()) {
    System.out.println(m.group());    // 555-1234
    System.out.println(m.group(1));   // 555
    System.out.println(m.group(2));   // 1234
}
